const listIntegrationVersions = `-- name: ListIntegrationVersions :many
SELECT v.id,v.setting_kind,v.sequence,v.state,v.version,v.latest_test_id,v.created_at,v.updated_at,v.activated_at,v.superseded_at,
 s.host,s.port,s.sender_name,s.sender_address,s.reply_to_address,s.connect_timeout_seconds,s.command_timeout_seconds,s.delivery_timeout_seconds,s.max_concurrency AS smtp_max_concurrency,
 o.model,o.timeout_seconds,o.max_concurrency AS openai_max_concurrency,o.enabled AS openai_enabled,
 p.enabled AS pesapal_enabled,p.environment,p.merchant_name,p.notification_id,COALESCE(p.credentials_secret_ref LIKE 'dbpesapal:v1:%',false)::boolean AS pesapal_credentials_configured
FROM platform_settings.integration_versions v LEFT JOIN platform_settings.smtp_versions s ON s.version_id=v.id LEFT JOIN platform_settings.openai_versions o ON o.version_id=v.id LEFT JOIN platform_settings.pesapal_versions p ON p.version_id=v.id
WHERE v.setting_kind=$1 AND ($2::bigint IS NULL OR v.sequence<$2) ORDER BY v.sequence DESC LIMIT $3
`

type ListIntegrationVersionsParams struct {
	SettingKind    string
	BeforeSequence *int64
	ResultLimit    int32
}

type ListIntegrationVersionsRow struct {
	ID                           pgtype.UUID
	SettingKind                  string
	Sequence                     int64
	State                        string
	Version                      int64
	LatestTestID                 pgtype.UUID
	CreatedAt                    pgtype.Timestamptz
	UpdatedAt                    pgtype.Timestamptz
	ActivatedAt                  pgtype.Timestamptz
	SupersededAt                 pgtype.Timestamptz
	Host                         *string
	Port                         *int32
	SenderName                   *string
	SenderAddress                *string
	ReplyToAddress               *string
	ConnectTimeoutSeconds        *int32
	CommandTimeoutSeconds        *int32
	DeliveryTimeoutSeconds       *int32
	SmtpMaxConcurrency           *int32
	Model                        *string
	TimeoutSeconds               *int32
	OpenaiMaxConcurrency         *int32
	OpenaiEnabled                *bool
	PesapalEnabled               *bool
	Environment                  *string
	MerchantName                 *string
	NotificationID               pgtype.UUID
	PesapalCredentialsConfigured bool
}

func (q *Queries) ListIntegrationVersions(ctx context.Context, arg ListIntegrationVersionsParams) ([]ListIntegrationVersionsRow, error) {
	rows, err := q.db.Query(ctx, listIntegrationVersions, arg.SettingKind, arg.BeforeSequence, arg.ResultLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListIntegrationVersionsRow{}
	for rows.Next() {
		var i ListIntegrationVersionsRow
		if err := rows.Scan(
			&i.ID,
			&i.SettingKind,
			&i.Sequence,
			&i.State,
			&i.Version,
			&i.LatestTestID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ActivatedAt,
			&i.SupersededAt,
			&i.Host,
			&i.Port,
			&i.SenderName,
			&i.SenderAddress,
			&i.ReplyToAddress,
			&i.ConnectTimeoutSeconds,
			&i.CommandTimeoutSeconds,
			&i.DeliveryTimeoutSeconds,
			&i.SmtpMaxConcurrency,
			&i.Model,
			&i.TimeoutSeconds,
			&i.OpenaiMaxConcurrency,
			&i.OpenaiEnabled,
			&i.PesapalEnabled,
			&i.Environment,
			&i.MerchantName,
			&i.NotificationID,
			&i.PesapalCredentialsConfigured,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

